    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed

        // 1) Read and validate inputs
        String u = username.getText() != null ? username.getText().trim() : "";
        String p = pass.getText() != null ? pass.getText().trim() : "";
        String m = mail.getText() != null ? mail.getText().trim() : "";

        if (u.isEmpty() || p.isEmpty() || m.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Please fill in all fields.", "Missing information", JOptionPane.WARNING_MESSAGE);
            return;
        }

        if (!isValidEmail(m)) {
            JOptionPane.showMessageDialog(this, "Please enter a valid email address.", "Invalid email", JOptionPane.WARNING_MESSAGE);
            return;
        }

        if (p.length() < 6) {
            JOptionPane.showMessageDialog(this, "Password must be at least 6 characters.", "Weak password", JOptionPane.WARNING_MESSAGE);
            return;
        }

        // 2) Confirm password (matching system) using a hidden input dialog
        JPasswordField confirmField = new JPasswordField();
        Object[] msg = {"Confirm Password:", confirmField};
        int option = JOptionPane.showConfirmDialog(this, msg, "Confirm Password", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (option != JOptionPane.OK_OPTION) {
            return; // user cancelled
        }
        String confirm = new String(confirmField.getPassword());
        if (!p.equals(confirm)) {
            JOptionPane.showMessageDialog(this, "Passwords do not match.", "Mismatch", JOptionPane.ERROR_MESSAGE);
            return;
        }

        // 3) DB connection settings (adjust as needed for your environment)
        String url = "jdbc:mysql://localhost:3306/data"; // DB name: data
        String user = "root"; // DB user
        String password = ""; // DB password

        try {
            Class.forName("com.mysql.cj.jdbc.Driver");

            try (Connection conn = DriverManager.getConnection(url, user, password)) {
                // 4) Check duplicates: username OR email already exists?
                String checkSql = "SELECT COUNT(*) FROM user_data WHERE username = ? OR mail = ?";
                try (PreparedStatement check = conn.prepareStatement(checkSql)) {
                    check.setString(1, u);
                    check.setString(2, m);
                    try (ResultSet rs = check.executeQuery()) {
                        rs.next();
                        int cnt = rs.getInt(1);
                        if (cnt > 0) {
                            JOptionPane.showMessageDialog(this, "Username or email already exists.", "Duplicate", JOptionPane.ERROR_MESSAGE);
                            return;
                        }
                    }
                }

                // 5) Insert
                String sql = "INSERT INTO user_data (username, password, mail) VALUES (?, ?, ?)";
                try (PreparedStatement ps = conn.prepareStatement(sql)) {
                    ps.setString(1, u);
                    ps.setString(2, p);
                    ps.setString(3, m);
                    int rows = ps.executeUpdate();
                    if (rows > 0) {
                        JOptionPane.showMessageDialog(this, "Registration successful.", "Success", JOptionPane.INFORMATION_MESSAGE);
                        clearFields();
                    } else {
                        JOptionPane.showMessageDialog(this, "Registration failed. Please try again.", "Failed", JOptionPane.ERROR_MESSAGE);
                    }
                }
            }
        } catch (ClassNotFoundException e) {
            JOptionPane.showMessageDialog(this, "MySQL JDBC Driver not found: " + e.getMessage(), "Driver Error", JOptionPane.ERROR_MESSAGE);
        } catch (SQLException e) {
            JOptionPane.showMessageDialog(this, "Database error: " + e.getMessage(), "DB Error", JOptionPane.ERROR_MESSAGE);
        }
    }//GEN-LAST:event_jButton1ActionPerformed

