    // Helpers
    private boolean isValidEmail(String email) {
        // Simple email pattern suitable for basic validation
        String regex = "^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$";
        return email != null && email.matches(regex);
    }

    private void clearFields() {
        username.setText("");
        pass.setText("");
        mail.setText("");
    }

